from pathlib import Path
import os
R=Path(os.environ.get('FLEET_ROOT',Path(__file__).resolve().parent));S=R/'site'
p=S/'index.html';s=p.read_text().replace('BAY STUDIO / 04','BAY STUDIO / 05').replace('Compare Studio 03','Compare Studio 04')
s=s.replace('</head>','<script defer src="draft.js"></script></head>')
s=s.replace('<button id="reset"','<button id="draftstudy">Draft study</button><button id="hullstudy">Shallow hull option</button><button id="reset"')
s=s.replace('</body>', '''<dialog id="draftdialog"><button id="draftclose" aria-label="Close draft study">×</button><div class="eyebrow">ATLAS BAY 25 / DESIGN STUDY</div><h2>Shallow water.<br>Without a made-up draft rating.</h2><p>The default keeps the approved hull. A separate <b>unvalidated shallow-aft-V option</b> keeps the same topsides, deck and T-top. These calculations compare hull volume at even keel, not measured boat performance.</p><div class="draft-controls"><label>Water <select id="waterkind"><option value="sea">Seawater · 1,025 kg/m³</option><option value="fresh">Freshwater · 1,000 kg/m³</option></select></label><label>Assumed TOTAL boat + load, kg <input id="massinput" type="number" min="1" max="9000" step="50" placeholder="Optional — no measured mass yet"></label></div><div id="draftresults">Loading calculation…</div><div id="draftsection"></div><div class="draft-warning"><b>Not a payload or operating-depth rating.</b> Total mass includes hull, top, glass, engine, rigging, batteries, fuel, people, tackle, ice and livewell water. Trim, stability, structure and actual all-up mass are not solved. Engine/propeller, trim tabs, strakes, transducers and trolling motor are separate clearance limits. Floating in 12 inches does not prove safe idling, acceleration or running in 12 inches.</div><p><b>What the alternative changes:</b> the aft bottom V becomes shallower while the chines, topsides and accommodation stay fixed. No engine is removed, hidden or scaled. This is not a tunnel-hull design or a qualified modification.</p><button id="inspectshallow">Inspect shallow-bottom option</button><p id="draftrefs"></p></dialog></body>''')
s=s.replace('<h2>Five assets.', '<p><b>Studio 05:</b> one outboard retained; six T-top rod holders; focused fishing additions; separate even-keel draft comparison. The shallow underbody is optional, unvalidated and not installed aboard Explorer.</p><h2>Five assets.')
p.write_text(s)
p=S/'viewer.js';s=p.read_text()
s=s.replace('previousBay=false,restoreCamera=null','previousBay=false,shallowBay=false,restoreCamera=null')
s=s.replace("sub:'Studio 04 · tailored detail'","sub:'Studio 05 · fishing + draft study'")
s=s.replace("tags:['Rigid T-top','Single outboard','Casting decks']","tags:['6 top rod holders','Single outboard','Draft not rated']")
s=s.replace('Approved hull. Tailored bolsters. Refined helm and hardware. The same fishing-first Bay, closer up.','One outboard. Six top holders. The approved hull, plus a separately labeled shallow-bottom study.')
s=s.replace("'Deck hardware','Outboard']","'Deck hardware','Outboard','Rod rack','Underbody']")
s=s.replace("'Outboard':[[-3.8,.45,0],[2.6,1.95,2.3],[-1.4,.65,1.1]]","'Outboard':[[-3.8,.45,0],[2.6,1.95,2.3],[-1.4,.65,1.1]],'Rod rack':[[-1.5,2.59,0],[1.0,.70,2.15],[-1.0,.45,.65]],'Underbody':[[-.6,.0,0],[8.7,2,3.0],[.30,-.45,1.3]]")
s=s.replace("file=id==='bay'&&previousBay?'ATLAS_Bay_25_Previous.glb':a.file","file=id==='bay'&&previousBay?'ATLAS_Bay_25_Previous.glb':id==='bay'&&shallowBay?'ATLAS_Bay_25_Shallow_Study.glb':a.file")
s=s.replace("previousBay?'Show Studio 04':'Compare Studio 03'","previousBay?'Show Studio 05':'Compare Studio 04'")
s=s.replace("'Studio 03 · comparison':a.sub","'Studio 04 · comparison':(id==='bay'&&shallowBay?'UNVALIDATED · shallow underbody':a.sub)")
s=s.replace("$('#baycompare').hidden=id!=='bay';","$('#baycompare').hidden=id!=='bay';$('#draftstudy').hidden=id!=='bay';$('#hullstudy').hidden=id!=='bay';$('#hullstudy').textContent=shallowBay?'Restore approved hull':'Shallow hull option';")
s=s.replace("function setView(name='Hero'){if(!defs[id])return;view=name;", "function setView(name='Hero'){if(!defs[id])return;if(id==='bay'&&name==='Underbody'){dry=true;styles();}view=name;")
s=s.replace("previousBay=!previousBay;load('bay')","shallowBay=false;previousBay=!previousBay;load('bay')")
s=s.replace("window.FLEET={load,pose", "function bayHull(value){if(!ready||id!=='bay')return;restoreCamera={pos:camera.position.toArray(),target:controls.target.toArray(),view,p};previousBay=false;shallowBay=!!value;load('bay')}$('#hullstudy').onclick=()=>bayHull(!shallowBay);\nwindow.FLEET={bayHull,load,pose")
s=s.replace("return{previousBay,asset:id", "return{previousBay,shallowBay,topRodHolders:id==='bay'?(previousBay?4:6):null,asset:id")
# Restore dry inspection when switching variants from Underbody camera.
s=s.replace("view=c.view;controls.update();}","view=c.view;if(view==='Underbody'){dry=true;styles();}controls.update();}")
p.write_text(s)
with (S/'style.css').open('a') as f:f.write('''\n#draftdialog{max-width:860px;width:calc(100vw - 40px);max-height:86vh;overflow:auto;background:#eef3f2;color:#1c3541;border:1px solid #9eafb5;border-radius:16px;padding:30px;box-sizing:border-box}#draftdialog::backdrop{background:#122632b8}#draftdialog h2{font-size:28px;margin:14px 0}#draftdialog p{font-size:14px;line-height:1.6}#draftclose{float:right;font-size:25px;background:none;border:0}#draftdialog button{border:1px solid #8fa6af;border-radius:6px;padding:9px 14px;cursor:pointer}#draftdialog select,#draftdialog input{padding:9px;background:white;border:1px solid #afbfbd;border-radius:5px;max-width:100%;box-sizing:border-box}.draft-controls{display:flex;gap:22px;flex-wrap:wrap;margin:20px 0}.draft-controls label{display:grid;gap:8px;font-size:12px}.draft-warning{background:#e3e7d8;padding:16px;font-size:12px;line-height:1.6;border-left:3px solid #879867}.draft-metrics{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:16px 0}.draft-card{border:1px solid #aebfbd;background:#fff;padding:16px;border-radius:8px}.draft-card strong{font-size:25px;display:block;margin:10px 0}.draft-card small{font-size:11px;line-height:1.4;display:block}#draftrefs a{display:block;font-size:12px;line-height:1.6}#draftsection svg{max-width:100%;height:auto}#draftresults .actual-unknown{font-size:12px;line-height:1.5}@media(max-width:650px){#draftdialog{padding:20px}.draft-metrics{grid-template-columns:1fr}.draft-controls{gap:12px}.actions{flex-wrap:wrap}.actions button{white-space:nowrap}}\n''')
